package cnagent

import (
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"os/exec"
	"strconv"
	"time"
)

// Probe classifications, ported verbatim from the probe() function of the
// cn_apply_watchdog script generated by bootstrap.sh (spec §6.1).
const (
	ProbeOK               = "OK"
	ProbeLink443Blocked   = "LINK_443_BLOCKED"
	ProbeLinkPortsBlocked = "LINK_PORTS_BLOCKED"
	ProbeCDown            = "C_DOWN"
	ProbeLocalBroken      = "LOCAL_BROKEN"
)

// Probe timeouts ported from the watchdog shell: HTTP probes get a 4s
// overall cap (curl --max-time 4), TCP port opens wait up to 2s
// (timeout 2 bash /dev/tcp), ICMP waits 1s (ping -W 1).
const (
	probeConnectTimeout = 2 * time.Second
	probeHTTPTimeout    = 4 * time.Second
	probePingTimeout    = 1 * time.Second
)

// localBrokenThreshold is how many control-group failures count as local
// internet breakage: internet_ok() passes only while fewer than 2 of the
// 3 control URLs fail.
const localBrokenThreshold = 2

// controlGroupURLs are the out-of-band control sites used to tell "our own
// internet is down" apart from "the gateway is down", ported from
// internet_ok() in the watchdog.
var controlGroupURLs = []string{
	"https://www.apple.com",
	"https://mirrors.aliyun.com",
	"https://pypi.org",
}

// ProbeResult is the outcome of one gateway probe round.
type ProbeResult struct {
	Result    string
	CheckedAt time.Time
	Detail    string
}

// prober abstracts the network operations used during a probe so tests can
// inject deterministic behavior; production uses realProber.
type prober interface {
	DialTCP(host string, port string, timeout time.Duration) error
	HTTPGet(url string, timeout time.Duration) error
	Ping(ip string, timeout time.Duration) bool
}

// ProbeGateway runs one watchdog probe round against gwIP using the live
// network. It is the production entry point; tests use ProbeGatewayWith.
func ProbeGateway(ctx context.Context, gwIP string, now func() time.Time) ProbeResult {
	return ProbeGatewayWith(ctx, gwIP, now, realProber{})
}

// ProbeGatewayWith runs one probe round through the injected prober. ctx is
// accepted for signature stability with future cancellation support; every
// network operation is already bounded by its own timeout.
//
// Classification order is a faithful port of the shell probe(): the control
// group runs first and local breakage (>= 2 of 3 control URLs failing) beats
// every gateway classification; then healthz (only attempted when TCP 80 is
// open) or TCP 443 open means OK, only 80 open means LINK_443_BLOCKED, ICMP
// and TCP 22 both failing means C_DOWN, and anything else is
// LINK_PORTS_BLOCKED.
func ProbeGatewayWith(ctx context.Context, gwIP string, now func() time.Time, p prober) ProbeResult {
	res := ProbeResult{CheckedAt: now()}

	// Detail records the first failed probe of the round.
	var detail string
	fail := func(format string, args ...any) {
		if detail == "" {
			detail = fmt.Sprintf(format, args...)
		}
	}

	// Control group first: local breakage beats every gateway classification.
	controlFails := 0
	for _, url := range controlGroupURLs {
		if err := p.HTTPGet(url, probeHTTPTimeout); err != nil {
			fail("control %s failed: %v", url, err)
			controlFails++
		}
	}
	if controlFails >= localBrokenThreshold {
		res.Result = ProbeLocalBroken
		res.Detail = detail
		return res
	}

	icmpOK := p.Ping(gwIP, probePingTimeout)
	if !icmpOK {
		fail("icmp ping %s failed", gwIP)
	}
	portOK := func(port string) bool {
		if err := p.DialTCP(gwIP, port, probeConnectTimeout); err != nil {
			fail("tcp %s connect failed: %v", port, err)
			return false
		}
		return true
	}
	p22 := portOK("22")
	p80 := portOK("80")
	p443 := portOK("443")

	// The shell only curls /healthz when TCP 80 is open.
	healthzURL := "http://" + gwIP + "/healthz"
	healthzOK := false
	if p80 {
		if err := p.HTTPGet(healthzURL, probeHTTPTimeout); err != nil {
			fail("healthz %s failed: %v", healthzURL, err)
		} else {
			healthzOK = true
		}
	}

	switch {
	case healthzOK || p443:
		res.Result = ProbeOK
	case p80:
		res.Result = ProbeLink443Blocked
	case !icmpOK && !p22:
		res.Result = ProbeCDown
	default:
		res.Result = ProbeLinkPortsBlocked
	}
	res.Detail = detail
	return res
}

// realProber performs the probe network operations against the live network.
type realProber struct{}

// DialTCP reports whether a TCP connection to host:port can be established.
func (realProber) DialTCP(host string, port string, timeout time.Duration) error {
	conn, err := net.DialTimeout("tcp", net.JoinHostPort(host, port), timeout)
	if err != nil {
		return err
	}
	return conn.Close()
}

// HTTPGet fetches url with an overall timeout, mirroring curl -fsS: any
// transport error or response code >= 400 is a failure.
func (realProber) HTTPGet(url string, timeout time.Duration) error {
	client := &http.Client{Timeout: timeout}
	resp, err := client.Get(url)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 400 {
		return fmt.Errorf("http get %s: unexpected status %d", url, resp.StatusCode)
	}
	_, _ = io.Copy(io.Discard, resp.Body)
	return nil
}

// Ping reports whether ip answers one ICMP echo within timeout, mirroring
// the watchdog's ping -c 1 -W 1. It shells out to the ping binary because
// raw ICMP sockets need CAP_NET_RAW and the machines that ran bootstrap.sh
// all ship ping.
func (realProber) Ping(ip string, timeout time.Duration) bool {
	secs := int(timeout / time.Second)
	if secs < 1 {
		secs = 1
	}
	cmd := exec.Command("ping", "-c", "1", "-W", strconv.Itoa(secs), ip)
	return cmd.Run() == nil
}
